pseudocode:
function solve(s, i, current, results) {
  if (i === s.length) { results.push(current); return; }
  if (isNaN(s[i])) {
    solve(s, i + 1, current + s[i].toLowerCase(), results);
    solve(s, i + 1, current + s[i].toUpperCase(), results);
  } else {
    solve(s, i + 1, current + s[i], results);
  }
}
